    10	function useMarkdownStyle(message: string | null = null, excludeStyles: Array<keyof MarkdownStyle> = defaultEmptyArray): MarkdownStyle {
    11	    const theme = useTheme();
    12	    const hasMessageOnlyEmojis = message != null && message.length > 0 && containsOnlyEmojis(message);
    13	    const emojiFontSize = hasMessageOnlyEmojis ? variables.fontSizeOnlyEmojis : variables.fontSizeNormal;
    14	
    15	    // this map is used to reset the styles that are not needed - passing undefined value can break the native side
    16	    const nonStylingDefaultValues: Record<string, string | number> = useMemo(
    17	        () => ({
    18	            color: theme.text,
    19	            backgroundColor: 'transparent',
    20	            marginLeft: 0,
    21	            paddingLeft: 0,
    22	            borderColor: 'transparent',
    23	            borderWidth: 0,
    24	        }),
    25	        [theme],
    26	    );
    27	
    28	    const markdownStyle = useMemo(() => {
    29	        const styling = {
    30	            syntax: {
    31	                color: theme.syntax,
    32	            },
    33	            link: {
    34	                color: theme.link,
    35	            },
    36	            h1: {
    37	                fontSize: variables.fontSizeLarge,
    38	            },
    39	            emoji: {
    40	                fontSize: emojiFontSize,
    41	            },
    42	            blockquote: {
    43	                borderColor: theme.border,
    44	                borderWidth: 4,
    45	                marginLeft: 0,
    46	                paddingLeft: 6,
    47	                /**
    48	                 * since blockquote has `inline-block` display -> padding-right is needed to prevent cursor overlapping
    49	                 * with last character of the text node.
    50	                 * As long as paddingRight > cursor.width, cursor will be displayed correctly.
    51	                 */
    52	                paddingRight: 1,
    53	            },
    54	            code: {
    55	                ...FontUtils.fontFamily.platform.MONOSPACE,
    56	                fontSize: 13, // TODO: should be 15 if inside h1, see StyleUtils.getCodeFontSize
    57	                color: theme.text,
    58	                backgroundColor: 'transparent',
    59	            },
    60	            pre: {
    61	                ...FontUtils.fontFamily.platform.MONOSPACE,
    62	                fontSize: 13,
    63	                color: theme.text,
    64	                backgroundColor: 'transparent',
    65	            },
    66	            mentionHere: {
    67	                color: theme.ourMentionText,
    68	                backgroundColor: theme.ourMentionBG,
    69	            },
    70	            mentionUser: {
    71	                color: theme.mentionText,
    72	                backgroundColor: theme.mentionBG,
    73	            },
    74	            mentionReport: {
    75	                color: theme.mentionText,
    76	                backgroundColor: theme.mentionBG,
    77	            },
    78	        };
    79	
    80	        if (excludeStyles.length) {
