    82	                const style: Record<string, unknown> = styling[key];
    83	                if (style) {
    84	                    Object.keys(style).forEach((styleKey) => {
    85	                        style[styleKey] = nonStylingDefaultValues[styleKey] ?? style[styleKey];
    86	                    });
    87	                }
    88	            });
    89	        }
    90	
    91	        return styling;
    92	    }, [theme, emojiFontSize, excludeStyles, nonStylingDefaultValues]);
    93	
    94	    return markdownStyle;
    95	}
